// Realistic motion keys converted from motion capture (CMU) and measured from Muybridge's plates.
// Generated by scripts/mocap/bvh-to-paper.ts (people) and scripts/mocap/muybridge-horse.ts (horses);
// do not edit the JSON by hand. Sources, licences and trims are in each clip's `meta` and in
// docs/art-references/motion-reference.md.
//
// Shape (the skeleton loader's): world angles in the rig convention (dir(a) = (sin a, cos a):
// 0 = hanging down, 90 = forward, 180 = up; an upright spine leaning forward is below 180), one key
// list per drawn facing, root offset and pelvis height in figure units (a man is 14 units tall),
// foot contacts for IK planting, and events (strike, release, smear, step).

import bow from './bow.json' with { type: 'json' };
import brace from './brace.json' with { type: 'json' };
import chop from './chop.json' with { type: 'json' };
import cutDiagonal from './cut-diagonal.json' with { type: 'json' };
import cutOverhead from './cut-overhead.json' with { type: 'json' };
import dieBack from './die-back.json' with { type: 'json' };
import dieCrumple from './die-crumple.json' with { type: 'json' };
import dieForward from './die-forward.json' with { type: 'json' };
import gun from './gun.json' with { type: 'json' };
import hit from './hit.json' with { type: 'json' };
import horseGallop from './horse-gallop.json' with { type: 'json' };
import horseWalk from './horse-walk.json' with { type: 'json' };
import idle from './idle.json' with { type: 'json' };
import javelin from './javelin.json' with { type: 'json' };
import march from './march.json' with { type: 'json' };
import run from './run.json' with { type: 'json' };
import thrust from './thrust.json' with { type: 'json' };
import walk from './walk.json' with { type: 'json' };

export type MotionFacing = 'se' | 'ne';

export interface MotionKey {
  /** Painted frame (0-based). */
  f: number;
  /** Curve to the next key (Spine bezier); missing = linear. */
  c?: [number, number, number, number];
  /** Pelvis offset from its rest place (units, y down). */
  root: number[];
  /** Pelvis height above the ground (units). */
  height: number;
  /** Feet planted (near = weapon side, far = shield side). */
  contact: { N: boolean; F: boolean };
  /** World angles (deg) of pelvis, spine, chest, neck, head and upperArm/forearm/hand/thigh/shin/foot + N/F. */
  bones: Record<string, number>;
  /** Yaw of the hips and shoulders against the facing (deg, + = right side forward). Informational. */
  twist?: { pelvis: number; chest: number };
}

export interface MotionClip {
  name: string;
  /** The Anim it was cut for (contract.ts name). */
  anim: string;
  frames: number;
  loop: boolean;
  angles: 'world';
  restHeight: number;
  /** People: pelvis height when standing (root is measured from (0, -restHip)). */
  restHip?: number;
  /** Missing: a man on foot. */
  body?: 'foot' | 'horse';
  /** True bone lengths (units) of the captured subject, scaled to restHeight. */
  lengths: Record<string, number>;
  facings: Record<MotionFacing, { keys: MotionKey[] }>;
  events: { f: number; name: string; len?: number; bone?: string }[];
  meta: Record<string, unknown>;
}

const all = [walk, march, run, idle, brace, cutOverhead, cutDiagonal, chop, thrust, bow, gun, javelin, hit, dieBack, dieForward, dieCrumple, horseWalk, horseGallop] as unknown as MotionClip[];

/** Every converted clip by name. */
export const MOTION: Readonly<Record<string, MotionClip>> = Object.fromEntries(all.map((c) => [c.name, c]));
/** Clip names per Anim name (contract.ts), the first being the default. */
export const MOTION_FOR: Readonly<Record<string, string[]>> = all.reduce<Record<string, string[]>>((m, c) => ((m[c.anim] ??= []).push(c.name), m), {});
